import {WebSocket} from 'ws';
import {InMemorySessionStore} from '../../infrastructure/stores/inMemorySessionStore.js';
import {fiveMemberStore} from '../../infrastructure/stores/sessionStoreTestSupport.js';
import type {SessionListOptions, SessionSummary} from '../../types/sessionStore.js';
import {validateMessage} from './validation.js';
import {answeringOrchestrator, connectClient, startEngineWith, stopEngines} from '../wsTestSupport.js';
import type {HalServerOptions} from '../createServer.js';

// spec: specs/hal-engine-websocket-protocol#4

const historyEnabled = {history: {enabled: true}} as unknown as Partial<HalServerOptions>;

const frameAfter = (client: WebSocket, send: () => void): Promise<Record<string, unknown>> =>
  new Promise((resolve, reject) => {
    const onError = (error: Error) => {
      client.off('message', onMessage);
      reject(error);
    };
    const onMessage = (raw: WebSocket.RawData) => resolve(JSON.parse(String(raw)) as Record<string, unknown>);
    client.once('error', onError);
    client.once('message', onMessage);
    send();
  });

const connected = (client: WebSocket): Promise<void> =>
  new Promise((resolve, reject) => {
    const onError = (error: Error) => reject(error);
    const onMessage = (raw: WebSocket.RawData) => {
      if ((JSON.parse(String(raw)) as {type: string}).type === 'connected') {
        client.off('error', onError);
        resolve();
      }
    };
    client.once('error', onError);
    client.on('message', onMessage);
  });

class RecordingStore extends InMemorySessionStore {
  readonly listCalls: Array<{userId: string | number; options: SessionListOptions | undefined}> = [];

  override listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
    this.listCalls.push({userId, options});
    return super.listFor(userId, options);
  }
}

afterEach(async () => {
  await stopEngines();
});

describe('conversation list WebSocket acceptance contract', () => {
  it('validates list_conversations and its limit and cursor fields', () => {
    expect(validateMessage({type: 'list_conversations'})).toEqual({
      valid: true,
      data: {type: 'list_conversations'},
    });

    for (const frame of [
      {type: 'list_conversations', limit: 0},
      {type: 'list_conversations', limit: 201},
      {type: 'list_conversations', limit: 1.5},
      {type: 'list_conversations', limit: '10'},
      {type: 'list_conversations', before: 'not a date'},
    ]) {
      const result = validateMessage(frame);
      expect(result.valid).toBe(false);
      if (!result.valid) expect(result.error).toContain('limit' in frame ? 'limit' : 'before');
    }
  });

  it('lists only the authenticated user conversations as ISO summaries and forwards list options', async () => {
    const store = new RecordingStore();
    for (const [sessionId, userId] of [
      ['older', 'user-1'],
      ['other-user', 'user-2'],
    ]) {
      const session = store.create(sessionId, userId);
      session.entries.push({role: 'user', content: sessionId, timestamp: '2026-01-01T00:00:00.000Z'});
    }

    const {url} = await startEngineWith({
      sessionStore: store,
      orchestrator: answeringOrchestrator,
      ...historyEnabled,
      wsAuth: async () => ({id: 'user-1'}),
    });
    const client = connectClient(url);
    await connected(client);

    const frame = await frameAfter(client, () =>
      client.send(JSON.stringify({type: 'list_conversations', userId: 'user-2', limit: 3}))
    );

    expect(frame.type).toBe('conversation_list');
    expect(frame.conversations).toEqual(
      expect.arrayContaining([
        expect.objectContaining({sessionId: 'older', entryCount: 1}),
        expect.objectContaining({sessionId: expect.any(String), entryCount: 0}),
      ])
    );
    expect(frame.conversations).not.toEqual(
      expect.arrayContaining([expect.objectContaining({sessionId: 'other-user'})])
    );
    for (const summary of frame.conversations as Array<Record<string, unknown>>) {
      expect(summary).toEqual({
        sessionId: expect.any(String),
        createdAt: expect.stringMatching(/^\d{4}-\d\d-\d\dT.*Z$/),
        updatedAt: expect.stringMatching(/^\d{4}-\d\d-\d\dT.*Z$/),
        entryCount: expect.any(Number),
      });
    }
    expect(store.listCalls).toEqual([{userId: 'user-1', options: {limit: 3, before: undefined}}]);
  });

  it('refuses the list when history is disabled or the store cannot list', async () => {
    const enabledStore = new InMemorySessionStore();
    const disabled = await startEngineWith({
      sessionStore: enabledStore,
      orchestrator: answeringOrchestrator,
      wsAuth: async () => ({id: 'user-1'}),
    });
    const disabledClient = connectClient(disabled.url);
    await connected(disabledClient);
    await expect(
      frameAfter(disabledClient, () => disabledClient.send(JSON.stringify({type: 'list_conversations'})))
    ).resolves.toMatchObject({type: 'error', code: 'UNSUPPORTED'});

    const unsupported = await startEngineWith({
      sessionStore: fiveMemberStore,
      orchestrator: answeringOrchestrator,
      ...historyEnabled,
      wsAuth: async () => ({id: 'user-1'}),
    });
    const unsupportedClient = connectClient(unsupported.url);
    await connected(unsupportedClient);
    await expect(
      frameAfter(unsupportedClient, () => unsupportedClient.send(JSON.stringify({type: 'list_conversations'})))
    ).resolves.toMatchObject({type: 'error', code: 'UNSUPPORTED'});
  });
});

