function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined) {
    if (
      typeof message.limit !== 'number' ||
      !Number.isInteger(message.limit) ||
      message.limit < 1 ||
      message.limit > 200
    ) {
      return {valid: false, error: 'limit must be an integer between 1 and 200'};
    }
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'before must be a cursor with updatedAt and sessionId'};
    }
    const cursor = message.before as Record<string, unknown>;
    if (typeof cursor.updatedAt !== 'string' || isNaN(Date.parse(cursor.updatedAt))) {
      return {valid: false, error: 'before.updatedAt must be a valid date string'};
    }
    if (typeof cursor.sessionId !== 'string') {
      return {valid: false, error: 'before.sessionId must be a string'};
    }
  }

  const result: ListConversationsMessage = {type: 'list_conversations'};
  if (message.limit !== undefined) result.limit = message.limit as number;
  if (message.before !== undefined) {
    const cursor = message.before as Record<string, unknown>;
    result.before = {updatedAt: cursor.updatedAt as string, sessionId: cursor.sessionId as string};
  }

  return {valid: true, data: result};
}

